import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, ElementRef, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { environment } from '../../../../environments/environment';
import jsPDF from 'jspdf';
declare var bootstrap: any;

@Component({
  selector: 'app-user-donations',
  standalone: true,
  imports: [CommonModule,FormsModule,ReactiveFormsModule],
  templateUrl: './user-donations.component.html',
  styleUrl: './user-donations.component.scss'
})
export class UserDonationsComponent {
   users: any[] = [];
      searchText: string = '';
      pageSize: number = 5;
      currentPage: number = 1;
      previewUrl: string | ArrayBuffer | null = null;
      toastMessage: string = '';
      newsForm: FormGroup;
      base64Image: string | null = null;
    
      pagination = {
        total: 0,
        page: 1,
        limit: this.pageSize
      };
    
      @ViewChild('errorToast', { static: false }) errorToast!: ElementRef;
    
      constructor(private fb: FormBuilder, private http: HttpClient) {
        this.newsForm = this.fb.group({
          title: ['', [Validators.required]],        // required
          newsLink: ['', [Validators.required]],     // required
          description: ['', [Validators.required]]   // required
        });
      }
    
      ngOnInit(): void {
        this.fetchtransactions();
      }
    
      // ✅ Fetch news with pagination
      fetchtransactions(page: number = 1, limit: number = this.pageSize) {
        this.http.get<any>(`${environment.apiUrl}/donations?page=${page}&limit=${limit}`).subscribe({
          next: (res) => {
            if (res.success && res.data?.data) {
              this.users = res.data.data;
              this.pagination = res.data.pagination;
              this.currentPage = page;
            }
          },
          error: (err) => {
            this.showErrorToast('Failed to fetch Transactions');
          } 
        });
      }
    
      // ✅ Pagination controls
      get totalPages(): number {
        return Math.ceil(this.pagination.total / this.pagination.limit);
      }
    
      changePage(page: number) {
        if (page >= 1 && page <= this.totalPages) {
          this.fetchtransactions(page, this.pageSize);
        }
      }
    
      goPrevious() {
        this.changePage(this.currentPage - 1);
      }
    
      goNext() {
        this.changePage(this.currentPage + 1);
      }
    
      onPageSizeChange(event: any) {
        this.pageSize = +event.target.value;
        this.currentPage = 1;
        this.fetchtransactions(this.currentPage, this.pageSize);
      }
    
    
  downloadReceipt(tx: any) {
    const doc = new jsPDF();
  
    // Header
    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.text("Indian Administrative", 14, 15);
    doc.text("Service Central Association", 14, 22);
  
    // Billed To Box
    doc.roundedRect(10, 30, 190, 50, 3, 3);
  
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.text("Billed To", 14, 38);
  
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
  
    const user = tx.createdBy;
  
    // LEFT SIDE USER DETAILS
    doc.text(`${user?.name || "N/A"}`, 14, 45);
    doc.text(`${user?.email || "N/A"}`, 14, 51);
    doc.text(`${user?.mobileNumber || "N/A"}`, 14, 57);
  
    // RIGHT SIDE DETAILS
    const rightX = 120;
  
    doc.text(`Member ID: ${user?.memberShipId || 'N/A'}`, rightX, 38);
    doc.text(`Designation: ${user?.designation || "N/A"}`, rightX, 45);
    doc.text(`Status: ${tx?.status || "N/A"}`, rightX, 52);
    doc.text(`Payment Date: ${tx?.createdAt ? new Date(tx.createdAt).toLocaleString() : 'N/A'}`, rightX, 59);
  
    // Order Number
    doc.setFontSize(10);
    doc.text(`Order Number: ${tx?.orderNumber || "N/A"}`, 14, 72);
  
    // TABLE HEADER
    let posY = 90;
    doc.setFillColor(240, 240, 240);
    doc.rect(10, posY, 190, 10, "F");
  
    doc.setFont("helvetica", "bold");
    doc.text("ITEM DETAIL", 14, posY + 7);
    doc.text("AMOUNT", 180, posY + 7, { align: "right" });
  
    // ITEM ROW
    posY += 15;
    doc.setFont("helvetica", "normal");
    doc.text("Donation Amount", 14, posY);
    doc.text(`Rs ${tx?.amount || 0}`, 180, posY, { align: "right" });
  
    // TOTAL SECTION
    posY += 20;
    doc.line(10, posY, 200, posY);
  
    posY += 10;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.text("Total:", 145, posY);
    doc.text(` Rs ${tx?.amount || 0}`, 180, posY, { align: "right" });
  
    // Signature
    posY += 100;
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text("Treasurer", 180, posY, { align: "right" });
  
    // Footer Note
    doc.setFontSize(9);
    doc.setTextColor(120);
    doc.text(
      "This is a system-generated receipt. For any queries, please contact IASCA.",
      105,
      285,
      { align: "center" }
    );
  
    // Save File
    doc.save(`Receipt_${tx?.orderNumber}.pdf`);
  }
  
    
    
      // ✅ Toast methods
      showErrorToast(message: string): void {
        this.toastMessage = message;
        const toastElement = this.errorToast.nativeElement;
        toastElement.classList.remove('bg-success');
        toastElement.classList.add('bg-danger');
        const toast = new bootstrap.Toast(toastElement);
        toast.show();
      }
    
      showSuccessToast(message: string) {
        this.toastMessage = message;
        const toastElement = this.errorToast.nativeElement;
        toastElement.classList.remove('bg-danger');
        toastElement.classList.add('bg-success');
        const toast = new bootstrap.Toast(toastElement);
        toast.show();
      }
    
}
